const int N = 1e5+10;
vector<int> g[N];
int col[N],dep[N],has[N];
void dfs(int x,int fa){
    dep[x]=dep[fa]+1;
    for(auto i:g[x]){
        if(i!=fa){
            dfs(i,x);
        }
    }
}
bool dfs2(int x,int fa){
    for(auto i:g[x]){
        if(i!=fa){
            auto res = dfs2(i,x);
            if(res==false)return false;
            if(has[i]||col[i])has[x]++;
        }
    }
    if(has[x]>1)return false;
    return true;
}
